"""One renderer for received gifts and authenticated operator previews."""
from html import escape

def render_gift(name,text,image,avatar='',amount=0,preview=False):
    coin=amount>0
    title='给你送来了星币！' if coin else '给你发来一条消息！'
    picture=image or '/updates/gift-art/'+('star-gift.png' if coin else 'star-letter.png')
    portrait='<img src="'+escape(avatar,quote=True)+'" alt="头像">' if avatar else '<span class="default-avatar"></span>'
    button='<button type="button">我知道了</button>' if preview else '<a href="starorbit://campaign/close">我知道了</a>'
    return '''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:system-ui,-apple-system,sans-serif}body{background:#eff2ff;color:#18366b;background:radial-gradient(ellipse at top left,#dce6ff,transparent 65%),linear-gradient(150deg,#f5f6ff,#e7ebff)}body.coin{color:#63320e;background:radial-gradient(ellipse at top left,#ffe3ad,transparent 60%),linear-gradient(145deg,#fff7df,#fff0ce)}main{padding:28px 22px 22px;min-height:100vh;display:flex;flex-direction:column;justify-content:center;gap:14px}.sender{display:flex;align-items:center;justify-content:center;gap:14px;padding-right:24px}.sender img,.default-avatar{width:52px;height:52px;object-fit:cover;border-radius:50%;flex:none}.default-avatar{background:url(/updates/gift-art/star-sprites.png) 0 0/200% 200%}.sender strong{font-size:20px;overflow-wrap:anywhere}.sender p{margin:4px 0 0;font-size:14px}.art{display:block;width:100%;max-height:34vh;object-fit:contain;border-radius:18px}.amount{text-align:center;font-size:34px;font-weight:750;color:#8c4b16}.amount small{font-size:14px;font-weight:500}blockquote{position:relative;white-space:pre-wrap;overflow-wrap:anywhere;margin:0;padding:22px 30px;border:1px solid #cbd4ed88;border-radius:20px;background:#ffffffb8;font-size:17px;line-height:1.65}blockquote:before{content:'“';position:absolute;left:10px;top:2px;color:#aabbe7;font-size:34px}.coin blockquote{border-color:#e8be7877}.coin blockquote:before{color:#e9b263}a,button{display:block;width:100%;border:0;border-radius:28px;padding:14px;background:linear-gradient(110deg,#5576ce,#4465b6);color:white;text-align:center;text-decoration:none;font:600 18px system-ui}.coin a,.coin button{background:linear-gradient(110deg,#c58a3f,#d09648)}@media(max-height:520px){main{padding:18px;gap:10px}.sender img,.default-avatar{width:42px;height:42px}.sender strong{font-size:17px}.art{max-height:29vh}blockquote{padding:14px 25px;font-size:15px}.amount{font-size:27px}}
/* Keep the reference card size fixed; long messages scroll inside the quote. */
html,body{height:100%;overflow:hidden}main{height:100vh;min-height:0;padding:26px 16px 18px;gap:12px}.sender{flex:none;gap:10px;padding-right:28px}.sender strong{font-size:17px}.sender p{font-size:12px}.sender img,.default-avatar{width:44px;height:44px}.art{flex:1 1 0;min-height:0;max-height:38vh;object-fit:contain}.amount{flex:none;font-size:30px}blockquote{flex:0 1 auto;min-height:65px;max-height:26vh;overflow:auto;padding:16px 24px;font-size:15px}main>a,main>button{flex:none;padding:12px;font-size:16px}@media(max-height:440px){main{padding:18px 12px 12px;gap:8px}.sender img,.default-avatar{width:34px;height:34px}.sender strong{font-size:15px}.amount{font-size:24px}blockquote{min-height:46px;padding:10px 22px;font-size:13px}main>a,main>button{padding:9px}}
main{justify-content:flex-start;padding:22px 16px 16px;gap:10px}.sender{min-height:40px;padding-right:22px;gap:9px}.sender img,.default-avatar{width:38px;height:38px}.sender strong{font-size:16px}.sender p{font-size:11px}.art{flex:0 1 auto;width:100%;height:auto;aspect-ratio:3/2;max-height:42vh;object-fit:contain}.amount{font-size:25px;line-height:1.15}blockquote{min-height:0;flex:0 1 auto;padding:12px 22px;font-size:14px;line-height:1.5;max-height:22vh}main>a,main>button{margin-top:auto;padding:10px;font-size:15px}@media(max-height:380px){main{padding:17px 12px 12px;gap:7px}.art{max-height:35vh}.sender img,.default-avatar{width:32px;height:32px}.sender strong{font-size:14px}blockquote{font-size:12px;padding:9px 19px}.amount{font-size:22px}}
</style></head><body class="'''+('coin' if coin else 'letter')+'"><main><header class="sender">'+portrait+'<div><strong>'+escape(name)+'</strong><p>'+title+'</p></div></header><img class="art" alt="礼物图片" src="'+escape(picture,quote=True)+'">'+('<div class="amount">+'+str(amount)+' <small>✦ 星币</small></div>' if coin else '')+'<blockquote>'+escape(text)+'</blockquote>'+button+'</main></body></html>'
